from itertools import combinations

def find_ramsey_graph(vertices, clique_avoid, indset_avoid):
    for attempt in range(1000):  # Try 1000 different graphs
        graph = []
        for u in range(vertices):
            for v in range(u + 1, vertices):
                if (u + v) % 2 == 0:  # Simple heuristic to create a graph
                    graph.append((u, v))
        # Check if the graph contains a clique of size clique_avoid
        for combo in combinations(range(vertices), clique_avoid):
            if all((u, v) in graph or (v, u) in graph for u, v in combinations(combo, 2)):
                break  # Found a clique, try another graph
        else:
            # Check if the graph contains an independent set of size indset_avoid
            for combo in combinations(range(vertices), indset_avoid):
                if all((u, v) not in graph and (v, u) not in graph for u, v in combinations(combo, 2)):
                    return graph  # Found a valid graph
    return "UNSATISFIABLE"

print(find_ramsey_graph(14, 5, 3))
